            { "type": { "kind": "string" }, "label": "head" },
            { "type": { "kind": "number" }, "label": "tail", "modifier": "rest" },
        ])
    );
    assert_eq!(
        prop(&out, "optional").1["elements"][1],
        json!({ "type": { "kind": "number" }, "modifier": "optional" })
    );
}

